//refAssemblies: TCAdmin.SDK.dll, TCAdmin.GameHosting.SDK.dll, TCAdmin.Scripting.dll, TCAdmin.Monitor.dll, System.Net.Http.dll, System.Text.Json.dll
using System;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text.Json;
using System.Threading.Tasks;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

void WriteLog(string s, int? progress = null)
{
    if (Globals.ThisTaskStepHandler != null)
    {
        Globals.ThisTaskStepHandler.UpdateProgress(progress: progress, log: s);
    }
    else if (Globals.ThisTaskStep != null)
    {
        if (progress.HasValue) Globals.ThisTaskStep.Progress = progress.Value;
        Globals.ThisTaskStep.AddDebugLog(s, skipDuplicates: true);
        Globals.TCATaskManager.Update(Globals.ThisTask, true);
    }
    else
    {
        Globals.ScriptConsole.WriteLine(s);
    }
}

// The official version feed names the current Windows x64 build and its SHA-256.
const string VersionFeed = "https://teamspeak.com/versions/server.json";
const string FallbackUrl = "http://downloads.tcadmin.net/games/ts3-windows64.aspx";

var gameFilesPath = Globals.ThisServer.Configuration.GameFilesPath;
var targetPath = Path.Combine(gameFilesPath, Globals.ThisGame.FileAndDirectoryConfig.AutoSetupFolderName);
var zipFile = Path.Combine(gameFilesPath, "__teamspeak3-server_win64.zip");
var extractPath = Path.Combine(gameFilesPath, "__teamspeak3-server_win64");

string url = FallbackUrl, checksum = null, version = "latest";
using (var http = new HttpClient { Timeout = TimeSpan.FromMinutes(10) })
{
    // teamspeak.com answers 403 to a request without a User-Agent.
    http.DefaultRequestHeaders.UserAgent.ParseAdd("TCAdmin/3.0");
    try
    {
        var json = await http.GetStringAsync(VersionFeed, Globals.ThisCancellationToken);
        using (var doc = JsonDocument.Parse(json))
        {
            var build = doc.RootElement.GetProperty("windows").GetProperty("x86_64");
            version = build.GetProperty("version").GetString();
            checksum = build.GetProperty("checksum").GetString();
            url = build.GetProperty("mirrors").EnumerateObject().First().Value.GetString();
        }
    }
    catch (Exception ex)
    {
        WriteLog($"Could not read the TeamSpeak version feed ({ex.Message}); using {FallbackUrl}.");
        url = FallbackUrl;
        checksum = null;
    }

    WriteLog($"Downloading TeamSpeak 3 server {version} from {url}...", 10);
    using (var response = await http.GetAsync(url, HttpCompletionOption.ResponseHeadersRead, Globals.ThisCancellationToken))
    {
        response.EnsureSuccessStatusCode();
        using (var fs = File.Create(zipFile))
            await response.Content.CopyToAsync(fs, Globals.ThisCancellationToken);
    }
}

if (!string.IsNullOrEmpty(checksum))
{
    string actual;
    using (var sha = SHA256.Create())
    using (var fs = File.OpenRead(zipFile))
        actual = Convert.ToHexString(sha.ComputeHash(fs));
    if (!actual.Equals(checksum, StringComparison.OrdinalIgnoreCase))
    {
        File.Delete(zipFile);
        throw new Exception($"The TeamSpeak download is corrupt: SHA-256 {actual} does not match the published {checksum}.");
    }
    WriteLog("Checksum verified.", 60);
}

WriteLog("Extracting...", 70);
if (Directory.Exists(extractPath)) Directory.Delete(extractPath, true);
ZipFile.ExtractToDirectory(zipFile, extractPath);
File.Delete(zipFile);

// The archive wraps everything in teamspeak3-server_win64/ - copy that folder's contents.
var source = extractPath;
var entries = Directory.GetFileSystemEntries(extractPath);
if (entries.Length == 1 && Directory.Exists(entries[0])) source = entries[0];

Directory.CreateDirectory(targetPath);
foreach (var dir in Directory.GetDirectories(source, "*", SearchOption.AllDirectories))
    Directory.CreateDirectory(Path.Combine(targetPath, Path.GetRelativePath(source, dir)));
foreach (var file in Directory.GetFiles(source, "*", SearchOption.AllDirectories))
    File.Copy(file, Path.Combine(targetPath, Path.GetRelativePath(source, file)), true);
Directory.Delete(extractPath, true);

if (!File.Exists(Path.Combine(targetPath, "ts3server.exe")))
    throw new Exception("ts3server.exe was not found in the downloaded archive.");
WriteLog($"TeamSpeak 3 server {version} is ready in {targetPath}.", 100);

//refAssemblies: TCAdmin.SDK.dll, TCAdmin.GameHosting.SDK.dll, TCAdmin.Scripting.dll, TCAdmin.Monitor.dll, Microsoft.Data.Sqlite.dll, Microsoft.EntityFrameworkCore.dll, EFCoreSecondLevelCacheInterceptor.dll
using System;
using EFCoreSecondLevelCacheInterceptor;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Sockets;
using System.Text;
using TCAdmin.SDK.Hubs.Models.GameQuery;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Master query: one row for the whole TeamSpeak instance.
//   MaxPlayers = sum of virtualserver_maxclients over ALL virtual servers (running or stopped)
//   NumPlayers = voice clients connected across all running virtual servers (ServerQuery clients excluded)
string address = Variables.Parse<string>("Address", null);
if (string.IsNullOrEmpty(address)) address = string.IsNullOrEmpty(ThisService.IPAddress) ? "127.0.0.1" : ThisService.IPAddress;
int port = Variables.Parse<int>("Port", 0);
if (port <= 0) port = ThisService.QueryPort;
string password = ThisService.Variables.Parse<string>("RconPassword", string.Empty);

int maxPlayers = 0, numPlayers = 0, running = 0;
var rules = new Dictionary<string, string>();
var players = new List<GameQueryPlayer>();
string version = "";

using (var ts = new Ts3Query(address, port, 3000))
{
    ts.Login("serveradmin", password);
    var ver = ts.SendSingle("version");
    version = Ts3Query.Str(ver, "version");

    var servers = ts.ServerList();
    long now = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
    foreach (var vs in servers)
    {
        int sid = Ts3Query.Int(vs, "virtualserver_id");
        string name = Ts3Query.Str(vs, "virtualserver_name");
        bool online = Ts3Query.Str(vs, "virtualserver_status") == "online";

        // serverlist omits maxclients for a stopped server; MaxClients reads its stored value.
        int max = ts.MaxClients(vs, ThisService.RootDirectory);
        bool slotsKnown = max >= 0;
        if (!slotsKnown) max = 0;

        int clients = online
            ? Math.Max(0, Ts3Query.Int(vs, "virtualserver_clientsonline") - Ts3Query.Int(vs, "virtualserver_queryclientsonline"))
            : 0;

        maxPlayers += max;
        numPlayers += clients;
        if (online) running++;
        rules[$"vs{sid}"] = $"{name} | port {Ts3Query.Str(vs, "virtualserver_port")} | {(online ? "online" : "offline")} | {clients}/{(slotsKnown ? max.ToString() : "?")}";

        if (online && clients > 0)
        {
            ts.Send($"use sid={sid}");
            foreach (var c in ts.Send("clientlist -times"))
            {
                if (Ts3Query.Int(c, "client_type") != 0) continue; // 1 = ServerQuery client
                long last = Ts3Query.Int(c, "client_lastconnected");
                players.Add(new GameQueryPlayer
                {
                    Name = Ts3Query.Str(c, "client_nickname"),
                    Team = name,
                    ConnectTime = last > 0 ? (int)Math.Max(0, now - last) : 0,
                });
            }
        }
    }
    rules["virtual_servers"] = servers.Count.ToString();
    rules["virtual_servers_running"] = running.ToString();
    rules["version"] = $"{version} {Ts3Query.Str(ver, "platform")}".Trim();
}

// The service name, read past the EF second-level cache and AFTER the ServerQuery work: the panel copies the query
// Name onto the service (and the header), so a name read before a rename that lands while TeamSpeak is being queried
// would be written back over it. NotCacheable = the database's current value; reading it last keeps that window tiny.
string serviceName = await ServiceManager.GetDbSet().AsNoTracking().NotCacheable()
    .Where(x => x.ServiceId == ThisService.ServiceId).Select(x => x.Name).FirstOrDefaultAsync(ThisCancellationToken);
if (string.IsNullOrWhiteSpace(serviceName)) serviceName = ThisService.Name;

Globals.ReturnValue = new GameQueryResponse
{
    Status = "online",
    Hostname = $"{address}:{port}",
    // The service's own name (panel settings or the Browser's Rename service): the panel header follows it within a
    // query tick. A TeamSpeak instance has no name of its own. Never "" (the panel would copy that). Live counts go in Map.
    Name = string.IsNullOrWhiteSpace(serviceName) ? null : serviceName,
    GameType = string.IsNullOrEmpty(version) ? "TeamSpeak 3" : "TeamSpeak 3 v" + version,
    Map = $"{rules["virtual_servers"]} virtual servers ({running} running)",
    NumPlayers = numPlayers,
    MaxPlayers = maxPlayers,
    Rules = rules,
    Players = players,
};

// ---------------------------------------------------------------------------------------------
// TeamSpeak 3 ServerQuery (raw/telnet) client. Every script of this blueprint carries the same
// copy: scripts cannot share code, so keep the copies identical when changing it.
// ---------------------------------------------------------------------------------------------
public class Ts3Exception : Exception
{
    public int ErrorId { get; }
    public Ts3Exception(int id, string message) : base($"TeamSpeak error {id}: {message}") { ErrorId = id; }
}

public class Ts3Reply
{
    public int ErrorId;
    public string ErrorMessage = "";
    public List<string> Lines = new List<string>();
    public List<Dictionary<string, string>> Rows => Ts3Query.ParseRows(string.Join("|", Lines));
}

public class Ts3Query : IDisposable
{
    public const int EmptyResultSet = 1281;

    private readonly TcpClient _tcp;
    private readonly NetworkStream _net;
    private readonly Stream _in;

    public Ts3Query(string host, int port, int timeoutMs = 5000)
    {
        _tcp = new TcpClient();
        try
        {
            if (!_tcp.ConnectAsync(host, port).Wait(timeoutMs))
                throw new TimeoutException("connection timed out");
        }
        catch (Exception ex)
        {
            _tcp.Dispose();
            var reason = ex is AggregateException ae && ae.InnerException != null ? ae.InnerException.Message : ex.Message;
            throw new IOException($"Cannot reach the TeamSpeak ServerQuery at {host}:{port} ({reason}). Is the TeamSpeak master running?");
        }
        _net = _tcp.GetStream();
        _net.ReadTimeout = timeoutMs;
        _net.WriteTimeout = timeoutMs;
        _in = new BufferedStream(_net);
        if (ReadLine() != "TS3")
            throw new IOException($"{host}:{port} is not a TeamSpeak 3 ServerQuery port.");
        ReadLine(); // "Welcome to the TeamSpeak 3 ServerQuery interface..."
    }

    // ServerQuery lines end with "\n\r": split on \n and drop every \r.
    private string ReadLine()
    {
        var buffer = new List<byte>(256);
        while (true)
        {
            int b = _in.ReadByte();
            if (b < 0)
            {
                if (buffer.Count == 0) throw new IOException("The TeamSpeak ServerQuery closed the connection.");
                break;
            }
            if (b == '\n') break;
            if (b != '\r') buffer.Add((byte)b);
        }
        return Encoding.UTF8.GetString(buffer.ToArray());
    }

    /// <summary>Sends one command and returns its reply without throwing on a TeamSpeak error.</summary>
    public Ts3Reply Execute(string command)
    {
        var bytes = Encoding.UTF8.GetBytes(command.Replace("\r", "").Replace("\n", " ").Trim() + "\n");
        _net.Write(bytes, 0, bytes.Length);
        var reply = new Ts3Reply();
        while (true)
        {
            var line = ReadLine();
            if (line.StartsWith("error ", StringComparison.Ordinal))
            {
                var error = ParseRow(line.Substring(6));
                int.TryParse(error.TryGetValue("id", out var id) ? id : "0", out reply.ErrorId);
                reply.ErrorMessage = error.TryGetValue("msg", out var msg) ? msg : "";
                if (error.TryGetValue("extra_msg", out var extra) && extra.Length > 0)
                    reply.ErrorMessage += " (" + extra + ")";
                if (error.TryGetValue("failed_permid", out var perm) && perm.Length > 0)
                    reply.ErrorMessage += " (missing permission " + perm + ")";
                return reply;
            }
            if (line.Length > 0 && !line.StartsWith("notify", StringComparison.Ordinal))
                reply.Lines.Add(line);
        }
    }

    /// <summary>Sends one command and returns its rows; throws on any TeamSpeak error except an empty result set.</summary>
    public List<Dictionary<string, string>> Send(string command)
    {
        var reply = Execute(command);
        if (reply.ErrorId == EmptyResultSet) return new List<Dictionary<string, string>>();
        if (reply.ErrorId != 0) throw new Ts3Exception(reply.ErrorId, reply.ErrorMessage);
        return reply.Rows;
    }

    public Dictionary<string, string> SendSingle(string command) =>
        Send(command).FirstOrDefault() ?? new Dictionary<string, string>();

    public void Login(string user, string password)
    {
        var reply = Execute($"login {Escape(user)} {Escape(password)}");
        if (reply.ErrorId != 0)
            throw new Ts3Exception(reply.ErrorId, "ServerQuery login as '" + user + "' failed: " + reply.ErrorMessage +
                ". The serveradmin password is the service's RCON password and is applied when the master starts - restart it after changing the RCON password.");
    }

    public List<Dictionary<string, string>> ServerList() => Send("serverlist")
        .Where(r => r.ContainsKey("virtualserver_id"))
        .OrderBy(r => Int(r, "virtualserver_id"))
        .ToList();

    /// <summary>Selects a virtual server, opening a stopped one in virtual mode.</summary>
    public void Use(int sid)
    {
        var reply = Execute($"use sid={sid} -virtual");
        if (reply.ErrorId == 2816)
            throw new Ts3Exception(2816, $"TeamSpeak will not open stopped virtual server #{sid} while the license's limit of running virtual servers is reached - stop another virtual server first");
        if (reply.ErrorId != 0) throw new Ts3Exception(reply.ErrorId, reply.ErrorMessage);
    }

    private Dictionary<int, int> _storedMaxClients;

    /// <summary>
    /// Slots of the virtual server in a serverlist row. A stopped server's row has no maxclients, so read
    /// the stored value from ts3server.sqlitedb (read-only, no side effects); fall back to "use -virtual"
    /// + serverinfo, which TeamSpeak refuses while the license's running-server limit is reached (-1).
    /// </summary>
    public int MaxClients(Dictionary<string, string> row, string rootDirectory)
    {
        int max = Int(row, "virtualserver_maxclients", -1);
        if (max >= 0) return max;
        int sid = Int(row, "virtualserver_id");
        if (_storedMaxClients == null) _storedMaxClients = ReadStoredMaxClients(Path.Combine(rootDirectory ?? "", "ts3server.sqlitedb"));
        if (_storedMaxClients.TryGetValue(sid, out max)) return max;
        try
        {
            Use(sid);
            return Int(SendSingle("serverinfo"), "virtualserver_maxclients", -1);
        }
        catch (Ts3Exception)
        {
            return -1;
        }
    }

    private static Dictionary<int, int> ReadStoredMaxClients(string dbPath)
    {
        var result = new Dictionary<int, int>();
        if (!File.Exists(dbPath)) return result; // another database plugin (MariaDB) - use ServerQuery
        try
        {
            var cs = new SqliteConnectionStringBuilder { DataSource = dbPath, Mode = SqliteOpenMode.ReadOnly, Pooling = false };
            using (var db = new SqliteConnection(cs.ToString()))
            {
                db.Open();
                using (var cmd = db.CreateCommand())
                {
                    cmd.CommandText = "SELECT server_id, value FROM server_properties WHERE ident = 'virtualserver_maxclients'";
                    using (var reader = cmd.ExecuteReader())
                        while (reader.Read())
                            if (int.TryParse(Convert.ToString(reader.GetValue(1)), out var m))
                                result[Convert.ToInt32(reader.GetValue(0))] = m;
                }
            }
        }
        catch
        {
            // Unreadable database: callers fall back to ServerQuery.
        }
        return result;
    }

    public void Dispose()
    {
        try { var quit = Encoding.UTF8.GetBytes("quit\n"); _net.Write(quit, 0, quit.Length); } catch { }
        _tcp.Dispose();
    }

    public static List<Dictionary<string, string>> ParseRows(string data) =>
        data.Length == 0
            ? new List<Dictionary<string, string>>()
            : data.Split('|').Select(ParseRow).ToList();

    public static Dictionary<string, string> ParseRow(string row)
    {
        var result = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        foreach (var token in row.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries))
        {
            int eq = token.IndexOf('=');
            if (eq < 0) result[token] = "";
            else result[token.Substring(0, eq)] = Unescape(token.Substring(eq + 1));
        }
        return result;
    }

    public static int Int(Dictionary<string, string> row, string key, int fallback = 0) =>
        row.TryGetValue(key, out var v) && int.TryParse(v, out var i) ? i : fallback;

    public static string Str(Dictionary<string, string> row, string key, string fallback = "") =>
        row.TryGetValue(key, out var v) ? v : fallback;

    public static string Escape(string value)
    {
        var sb = new StringBuilder();
        foreach (char c in value ?? "")
        {
            switch (c)
            {
                case '\\': sb.Append(@"\\"); break;
                case '/': sb.Append(@"\/"); break;
                case ' ': sb.Append(@"\s"); break;
                case '|': sb.Append(@"\p"); break;
                case '\a': sb.Append(@"\a"); break;
                case '\b': sb.Append(@"\b"); break;
                case '\f': sb.Append(@"\f"); break;
                case '\n': sb.Append(@"\n"); break;
                case '\r': sb.Append(@"\r"); break;
                case '\t': sb.Append(@"\t"); break;
                case '\v': sb.Append(@"\v"); break;
                default: sb.Append(c); break;
            }
        }
        return sb.ToString();
    }

    public static string Unescape(string value)
    {
        var sb = new StringBuilder();
        for (int i = 0; i < value.Length; i++)
        {
            char c = value[i];
            if (c != '\\' || i == value.Length - 1) { sb.Append(c); continue; }
            char n = value[++i];
            switch (n)
            {
                case 's': sb.Append(' '); break;
                case 'p': sb.Append('|'); break;
                case '/': sb.Append('/'); break;
                case '\\': sb.Append('\\'); break;
                case 'a': sb.Append('\a'); break;
                case 'b': sb.Append('\b'); break;
                case 'f': sb.Append('\f'); break;
                case 'n': sb.Append('\n'); break;
                case 'r': sb.Append('\r'); break;
                case 't': sb.Append('\t'); break;
                case 'v': sb.Append('\v'); break;
                default: sb.Append('\\').Append(n); break;
            }
        }
        return sb.ToString();
    }
}

//refAssemblies: TCAdmin.SDK.dll, TCAdmin.GameHosting.SDK.dll, TCAdmin.Scripting.dll, TCAdmin.Monitor.dll, Microsoft.Data.Sqlite.dll
using System;
using Microsoft.Data.Sqlite;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Sockets;
using System.Text;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// RCON console for the TeamSpeak master: every console line is run as ServerQuery command(s),
// logged in as serveradmin with the service's RCON password. Each line is a new session, so
// chain commands that need a selected virtual server with ';', e.g.  use sid=1; clientlist
string address = Variables.Parse<string>("Address", null);
if (string.IsNullOrEmpty(address)) address = string.IsNullOrEmpty(ThisService.IPAddress) ? "127.0.0.1" : ThisService.IPAddress;
int port = Variables.Parse<int>("Port", 0);
if (port <= 0) port = ThisService.RconPort;
string password = Variables.Parse<string>("Password", null);
if (string.IsNullOrEmpty(password)) password = ThisService.Variables.Parse<string>("RconPassword", string.Empty);
string input = (Variables.Parse<string>("Command", string.Empty) ?? string.Empty).Trim();

var commands = input.Split(';').Select(c => c.Trim()).Where(c => c.Length > 0).ToList();
var output = new StringBuilder();

if (commands.Count == 0)
{
    output.AppendLine("TeamSpeak 3 ServerQuery console (logged in as serveradmin).");
    output.AppendLine("Examples: serverlist | hostinfo | version | use sid=1; clientlist | use sid=1; serverinfo | help");
    output.AppendLine("Values use ServerQuery escaping (space = \\s). Chain commands with ';' - each line is a new session.");
}
else if (commands.Any(c => c.Equals("quit", StringComparison.OrdinalIgnoreCase) || c.Equals("logout", StringComparison.OrdinalIgnoreCase)))
{
    output.AppendLine("'quit' and 'logout' are not needed - every console line opens and closes its own session.");
}
else
{
    using (var ts = new Ts3Query(address, port, 5000))
    {
        ts.Login("serveradmin", password);
        foreach (var command in commands)
        {
            if (commands.Count > 1) output.AppendLine("> " + command);
            var reply = ts.Execute(command);
            foreach (var line in reply.Lines)
            {
                // List replies (key=value rows separated by '|') are printed one unescaped row per line;
                // free text such as 'help' is printed as-is.
                var tokens = line.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
                bool isRows = tokens.Any(t => t.Contains('=')) &&
                              tokens.All(t => System.Text.RegularExpressions.Regex.IsMatch(t, @"^[A-Za-z_0-9\-]+(=\S*)?(\|[A-Za-z_0-9\-]+(=\S*)?)*$"));
                if (isRows)
                    foreach (var row in line.Split('|'))
                        output.AppendLine(Ts3Query.Unescape(row));
                else
                    output.AppendLine(line);
            }
            if (reply.ErrorId == 0)
            {
                if (reply.Lines.Count == 0) output.AppendLine("ok");
            }
            else if (reply.ErrorId == Ts3Query.EmptyResultSet)
            {
                output.AppendLine("(empty result)");
            }
            else
            {
                output.AppendLine($"error {reply.ErrorId}: {reply.ErrorMessage}");
            }
        }
    }
}

Globals.ReturnValue = output.ToString().TrimEnd();

