using System;
using Microsoft.Data.Sqlite;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Sockets;
using System.Text;
using System.Threading;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// ts3server.exe has no console input, so TCAdmin's stop would just close/kill the process.
// Ask the instance to shut down through ServerQuery instead (saves and stops every virtual
// server cleanly), then wait for it to exit. Never fails the stop: TCAdmin still kills it after.
string host = string.IsNullOrEmpty(ThisService.IPAddress) ? "127.0.0.1" : ThisService.IPAddress;
int port = ThisService.QueryPort;
string password = ThisService.Variables.Parse<string>("RconPassword", string.Empty);

bool requested = false;
try
{
    using (var ts = new Ts3Query(host, port, 3000))
    {
        ts.Login("serveradmin", password);
        var reply = ts.Execute("serverprocessstop reasonmsg=" + Ts3Query.Escape("The server is shutting down."));
        requested = reply.ErrorId == 0;
        if (!requested) ScriptConsole.WriteLine("TeamSpeak refused serverprocessstop: " + reply.ErrorMessage);
    }
}
catch (Exception ex)
{
    ScriptConsole.WriteLine("Graceful TeamSpeak shutdown skipped: " + ex.Message);
}

// This service's ts3server.exe, matched by its path under the service root.
string root = Path.GetFullPath(ThisService.RootDirectory).TrimEnd(Path.DirectorySeparatorChar) + Path.DirectorySeparatorChar;
bool Running()
{
    bool found = false;
    foreach (var p in System.Diagnostics.Process.GetProcessesByName("ts3server"))
    {
        try
        {
            if (p.MainModule?.FileName?.StartsWith(root, StringComparison.OrdinalIgnoreCase) == true) found = true;
        }
        catch
        {
            // Exited meanwhile or not readable: not ours to wait for.
        }
        finally
        {
            p.Dispose();
        }
    }
    return found;
}

if (requested)
{
    var deadline = DateTime.UtcNow.AddSeconds(20);
    bool stopped = false;
    while (DateTime.UtcNow < deadline)
    {
        Thread.Sleep(250);
        if (!Running())
        {
            stopped = true;
            break;
        }
    }
    ScriptConsole.WriteLine(stopped
        ? "TeamSpeak master shut down gracefully."
        : "TeamSpeak master did not exit within 20 seconds; TCAdmin will stop it.");
}

