using System.Text;
using TCAdmin.SDK.Database.Entities;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE


// API function "TsHost": the TeamSpeak 3 master instance, for the TeamSpeak Browser page.
// TsAction = info | broadcast | logs | rename.
// info       -> version, uptime, totals, bandwidth, ports and how many virtual servers are TCAdmin services
// broadcast  TsMessage -> sends it to every client on every virtual server (gm)
// logs       TsLines (max 100) -> { lines, fileSize } the last lines of the instance log, oldest first
// rename     TsName -> renames this TCAdmin service (the master query reports the service name, so the panel header follows within a tick)
var action = Action();
if (action == "rename")
{
    // Panel-only: TeamSpeak has no instance name, so this needs no ServerQuery connection.
    string name = Arg("TsName").Trim();
    if (name.Length == 0) throw Fail("TsName (the service name) is required.");
    if (name.Length > 128) throw Fail("The service name can be at most 128 characters.");
    var service = await ServiceManager.GetAsync(ThisService.ServiceId)
                  ?? throw Fail($"Service {ThisService.ServiceId} was not found.");
    service.Name = name;
    ServiceManager.TCAdminDbContext.Entry(service).Property(x => x.Name).IsModified = true;
    // UpdateAsync (not a bare SaveChangesAsync) stamps ModifiedDate: the stats collector ignores a cached
    // query result older than that stamp instead of writing the old name back over the rename.
    await ServiceManager.UpdateAsync(service, true, ThisCancellationToken);
    Globals.ReturnValue = new { ok = true, name };
}
else using (var ts = Ts3Connect())
{
    switch (action)
    {
        case "info":
        {
            var version = ts.SendSingle("version");
            var host = ts.SendSingle("hostinfo");
            var instance = ts.SendSingle("instanceinfo");
            var servers = ts.ServerList();
            var panel = PanelVirtualServers();
            Globals.ReturnValue = new Dictionary<string, object>
            {
                ["version"] = Nz(version, "version"), ["build"] = Nz(version, "build"), ["platform"] = Nz(version, "platform"),
                ["uptimeSeconds"] = Nl(host, "instance_uptime"), ["serverTimeUtc"] = Nl(host, "host_timestamp_utc"),
                ["virtualServersTotal"] = servers.Count, ["virtualServersRunning"] = Ni(host, "virtualservers_running_total"),
                ["virtualServersManagedByPanel"] = panel.Count,
                ["clientsOnline"] = Ni(host, "virtualservers_total_clients_online"), ["maxClients"] = Ni(host, "virtualservers_total_maxclients"),
                ["channelsOnline"] = Ni(host, "virtualservers_total_channels_online"),
                ["bytesSent"] = Nl(host, "connection_bytes_sent_total"), ["bytesReceived"] = Nl(host, "connection_bytes_received_total"),
                ["bandwidthSent"] = Nl(host, "connection_bandwidth_sent_last_second_total"), ["bandwidthReceived"] = Nl(host, "connection_bandwidth_received_last_second_total"),
                ["fileTransferBandwidthSent"] = Nl(host, "connection_filetransfer_bandwidth_sent"), ["fileTransferBandwidthReceived"] = Nl(host, "connection_filetransfer_bandwidth_received"),
                ["fileTransferBytesSent"] = Nl(host, "connection_filetransfer_bytes_sent_total"), ["fileTransferBytesReceived"] = Nl(host, "connection_filetransfer_bytes_received_total"),
                ["queryPort"] = ThisService.QueryPort, ["fileTransferPort"] = Ni(instance, "serverinstance_filetransfer_port"),
                ["databaseVersion"] = Ni(instance, "serverinstance_database_version"),
                ["maxDownloadBandwidth"] = Nl(instance, "serverinstance_max_download_total_bandwidth"), ["maxUploadBandwidth"] = Nl(instance, "serverinstance_max_upload_total_bandwidth"),
                ["ipAddress"] = ThisService.IPAddress ?? "", ["rootDirectory"] = ThisService.RootDirectory ?? ""
            };
            break;
        }
        case "broadcast":
        {
            var message = Arg("TsMessage").Trim(); if (message.Length == 0) throw Fail("TsMessage is required.");
            ts.Send($"gm msg={Ts3Query.Escape(message)}");
            Globals.ReturnValue = new { ok = true };
            break;
        }
        case "logs":
            Globals.ReturnValue = LogPage(ts, IntArg("TsLines", 100), instance: true);
            break;
        default:
            throw Fail($"Unknown TsAction '{action}'. Use info, broadcast, logs or rename.");
    }
}


// ---------------------------------------------------------------------------------------------
// API-function helpers. The TeamSpeak Browser page calls these scripts through
// TCAdmin.Script.Execute(name, { TsAction: "...", ... }); every argument is a declared script
// input variable (Ts*). The result is Globals.ReturnValue; a thrown exception is the call's error.
// Every TeamSpeak Browser function of this blueprint carries the same copy - keep them identical.
// ---------------------------------------------------------------------------------------------
string Arg(string name, string fallback = "")
{
    var value = GetValue<object>(name);
    var text = value == null ? "" : Convert.ToString(value, CultureInfo.InvariantCulture) ?? "";
    return text.Length == 0 ? fallback : text;
}
int IntArg(string name, int fallback = 0) =>
    double.TryParse(Arg(name), NumberStyles.Float, CultureInfo.InvariantCulture, out var d) ? (int)Math.Round(d) : fallback;
bool BoolArg(string name) => Arg(name).Equals("true", StringComparison.OrdinalIgnoreCase) || Arg(name) == "1";
string Action() => Arg("TsAction").Trim().ToLowerInvariant();
Exception Fail(string message) => new Exception(message);
string Nz(Dictionary<string, string> row, string key) => Ts3Query.Str(row, key);
int Ni(Dictionary<string, string> row, string key, int fallback = 0) => Ts3Query.Int(row, key, fallback);
long Nl(Dictionary<string, string> row, string key) => long.TryParse(Ts3Query.Str(row, key), out var l) ? l : 0;

/// <summary>Server groups of the selected virtual server: sgid -> name (regular groups only).</summary>
Dictionary<int, string> ServerGroups(Ts3Query ts) =>
    ts.Send("servergrouplist").Where(g => Ni(g, "type") == 1 && g.ContainsKey("sgid"))
      .ToDictionary(g => Ni(g, "sgid"), g => Nz(g, "name"));

/// <summary>Channels of the selected virtual server as browser rows, in TeamSpeak's display order.</summary>
List<Dictionary<string, object>> ChannelRows(Ts3Query ts)
{
    var rows = ts.Send("channellist -topic -flags -voice -limits").Where(c => c.ContainsKey("cid")).ToList();
    var byParent = rows.GroupBy(c => Ni(c, "pid")).ToDictionary(g => g.Key, g => g.ToList());
    var ordered = new List<Dictionary<string, object>>();
    void Walk(int pid, int depth)
    {
        if (!byParent.TryGetValue(pid, out var children)) return;
        // channel_order is the id of the channel ABOVE a channel; 0 = first.
        var remaining = children.ToList();
        int previous = 0;
        while (remaining.Count > 0)
        {
            var next = remaining.FirstOrDefault(c => Ni(c, "channel_order") == previous) ?? remaining[0];
            remaining.Remove(next);
            int cid = Ni(next, "cid");
            ordered.Add(new Dictionary<string, object>
            {
                ["cid"] = cid, ["pid"] = pid, ["depth"] = depth,
                ["name"] = Nz(next, "channel_name"), ["topic"] = Nz(next, "channel_topic"),
                ["clients"] = Ni(next, "total_clients"),
                ["maxClients"] = Ni(next, "channel_flag_maxclients_unlimited") == 1 ? -1 : Ni(next, "channel_maxclients", -1),
                ["permanent"] = Ni(next, "channel_flag_permanent") == 1,
                ["semiPermanent"] = Ni(next, "channel_flag_semi_permanent") == 1,
                ["isDefault"] = Ni(next, "channel_flag_default") == 1,
                ["passworded"] = Ni(next, "channel_flag_password") == 1,
                ["codec"] = Ni(next, "channel_codec"), ["codecQuality"] = Ni(next, "channel_codec_quality"),
                ["neededTalkPower"] = Ni(next, "channel_needed_talk_power"),
                ["neededSubscribePower"] = Ni(next, "channel_needed_subscribe_power")
            });
            previous = cid;
            Walk(cid, depth + 1);
        }
    }
    Walk(0, 0);
    return ordered;
}

