/// <summary>
/// The last N lines of the log (TeamSpeak caps a call at 100; its begin_pos only pages BACKWARDS, so there is
/// no "lines after X" read). fileSize lets a poller skip a redraw when nothing was written.
/// </summary>
Dictionary<string, object> LogPage(Ts3Query ts, int lines, bool instance)
{
    lines = Math.Clamp(lines <= 0 ? 100 : lines, 1, 100);
    var rows = ts.Send($"logview lines={lines}" + (instance ? " instance=1" : ""));
    var head = rows.FirstOrDefault(r => r.ContainsKey("file_size")) ?? new Dictionary<string, string>();
    return new Dictionary<string, object>
    {
        ["lines"] = rows.Where(r => r.ContainsKey("l")).Select(r => Nz(r, "l")).ToList(),
        ["fileSize"] = Nl(head, "file_size")
    };
}


// ---------------------------------------------------------------------------------------------
// Master connection: this service IS the TeamSpeak 3 master. Scope = every virtual server.
// ---------------------------------------------------------------------------------------------
Ts3Query Ts3Connect(int timeoutMs = 5000)
{
    var host = string.IsNullOrEmpty(ThisService.IPAddress) ? "127.0.0.1" : ThisService.IPAddress;
    var ts = new Ts3Query(host, ThisService.QueryPort, timeoutMs);
    try { ts.Login("serveradmin", ThisService.Variables.Parse<string>("RconPassword", string.Empty)); }
    catch { ts.Dispose(); throw; }
    return ts;
}

/// <summary>The TsSid argument; the browser always names the virtual server it works on.</summary>
int RequireSid()
{
    int sid = IntArg("TsSid");
    if (sid <= 0) throw Fail("TsSid (the virtual server id) is required.");
    return sid;
}

/// <summary>Hosted TCAdmin services living in this master, keyed by TeamSpeak virtual server id.</summary>
Dictionary<int, Dictionary<string, object>> PanelVirtualServers()
{
    var result = new Dictionary<int, Dictionary<string, object>>();
    var children = GameServiceManager.TCAdminDbContext.GameServices.AsNoTracking()
        .Where(s => s.HostServiceId == ThisService.ServiceId)
        .Select(s => new { s.ServiceId, s.Name, s.Variables, s.Status })
        .ToList();
    foreach (var child in children)
        if (int.TryParse(child.Variables.Parse<string>("Sid", string.Empty), out var sid) && sid > 0)
            result[sid] = new Dictionary<string, object> { ["serviceId"] = child.ServiceId, ["name"] = child.Name ?? "", ["status"] = child.Status.ToString() };
    return result;
}

/// <summary>A virtual server that is a TCAdmin service is managed from that service's page, so the panel's status and settings never drift.</summary>
void RequireUnmanaged(Dictionary<int, Dictionary<string, object>> panel, int sid, string verb)
{
    if (panel.TryGetValue(sid, out var svc))
        throw Fail($"Virtual server #{sid} is the TCAdmin service '{svc["name"]}' (#{svc["serviceId"]}). {verb} it from that service's page.");
}

/// <summary>Selects a virtual server for the following commands; a stopped one opens in virtual mode.</summary>
int UseSid(Ts3Query ts)
{
    int sid = RequireSid();
    ts.Use(sid);
    return sid;
}

// ---------------------------------------------------------------------------------------------
// TeamSpeak 3 ServerQuery (raw/telnet) client. Every script of this blueprint carries the same
// copy: scripts cannot share code, so keep the copies identical when changing it.
// ---------------------------------------------------------------------------------------------
public class Ts3Exception : Exception
{
    public int ErrorId { get; }
    public Ts3Exception(int id, string message) : base($"TeamSpeak error {id}: {message}") { ErrorId = id; }
}

public class Ts3Reply
{
    public int ErrorId;
    public string ErrorMessage = "";
    public List<string> Lines = new List<string>();
    public List<Dictionary<string, string>> Rows => Ts3Query.ParseRows(string.Join("|", Lines));
}

public class Ts3Query : IDisposable
{
    public const int EmptyResultSet = 1281;

    private readonly TcpClient _tcp;
    private readonly NetworkStream _net;
    private readonly Stream _in;

    public Ts3Query(string host, int port, int timeoutMs = 5000)
    {
        _tcp = new TcpClient();
        try
        {
            if (!_tcp.ConnectAsync(host, port).Wait(timeoutMs))
                throw new TimeoutException("connection timed out");
        }
        catch (Exception ex)
        {
            _tcp.Dispose();
            var reason = ex is AggregateException ae && ae.InnerException != null ? ae.InnerException.Message : ex.Message;
            throw new IOException($"Cannot reach the TeamSpeak ServerQuery at {host}:{port} ({reason}). Is the TeamSpeak master running?");
        }
        _net = _tcp.GetStream();
        _net.ReadTimeout = timeoutMs;
        _net.WriteTimeout = timeoutMs;
        _in = new BufferedStream(_net);
        if (ReadLine() != "TS3")
            throw new IOException($"{host}:{port} is not a TeamSpeak 3 ServerQuery port.");
        ReadLine(); // "Welcome to the TeamSpeak 3 ServerQuery interface..."
    }

    // ServerQuery lines end with "\n\r": split on \n and drop every \r.
    private string ReadLine()
    {
        var buffer = new List<byte>(256);
        while (true)
        {
            int b = _in.ReadByte();
            if (b < 0)
            {
                if (buffer.Count == 0) throw new IOException("The TeamSpeak ServerQuery closed the connection.");
                break;
            }
            if (b == '\n') break;
            if (b != '\r') buffer.Add((byte)b);
        }
        return Encoding.UTF8.GetString(buffer.ToArray());
    }

    /// <summary>Sends one command and returns its reply without throwing on a TeamSpeak error.</summary>
    public Ts3Reply Execute(string command)
    {
        var bytes = Encoding.UTF8.GetBytes(command.Replace("\r", "").Replace("\n", " ").Trim() + "\n");
        _net.Write(bytes, 0, bytes.Length);
        var reply = new Ts3Reply();
        while (true)
        {
            var line = ReadLine();
            if (line.StartsWith("error ", StringComparison.Ordinal))
            {
                var error = ParseRow(line.Substring(6));
                int.TryParse(error.TryGetValue("id", out var id) ? id : "0", out reply.ErrorId);
                reply.ErrorMessage = error.TryGetValue("msg", out var msg) ? msg : "";
                if (error.TryGetValue("extra_msg", out var extra) && extra.Length > 0)
                    reply.ErrorMessage += " (" + extra + ")";
                if (error.TryGetValue("failed_permid", out var perm) && perm.Length > 0)
                    reply.ErrorMessage += " (missing permission " + perm + ")";
                return reply;
            }
            if (line.Length > 0 && !line.StartsWith("notify", StringComparison.Ordinal))
                reply.Lines.Add(line);
        }
    }

    /// <summary>Sends one command and returns its rows; throws on any TeamSpeak error except an empty result set.</summary>
    public List<Dictionary<string, string>> Send(string command)
    {
        var reply = Execute(command);
        if (reply.ErrorId == EmptyResultSet) return new List<Dictionary<string, string>>();
        if (reply.ErrorId != 0) throw new Ts3Exception(reply.ErrorId, reply.ErrorMessage);
        return reply.Rows;
    }

    public Dictionary<string, string> SendSingle(string command) =>
        Send(command).FirstOrDefault() ?? new Dictionary<string, string>();

    public void Login(string user, string password)
    {
        var reply = Execute($"login {Escape(user)} {Escape(password)}");
        if (reply.ErrorId != 0)
            throw new Ts3Exception(reply.ErrorId, "ServerQuery login as '" + user + "' failed: " + reply.ErrorMessage +
                ". The serveradmin password is the service's RCON password and is applied when the master starts - restart it after changing the RCON password.");
    }

    public List<Dictionary<string, string>> ServerList() => Send("serverlist")
        .Where(r => r.ContainsKey("virtualserver_id"))
        .OrderBy(r => Int(r, "virtualserver_id"))
        .ToList();

    /// <summary>Selects a virtual server, opening a stopped one in virtual mode.</summary>
    public void Use(int sid)
    {
        var reply = Execute($"use sid={sid} -virtual");
        if (reply.ErrorId == 2816)
            throw new Ts3Exception(2816, $"TeamSpeak will not open stopped virtual server #{sid} while the license's limit of running virtual servers is reached - stop another virtual server first");
        if (reply.ErrorId != 0) throw new Ts3Exception(reply.ErrorId, reply.ErrorMessage);
    }

    private Dictionary<int, int> _storedMaxClients;

    /// <summary>
    /// Slots of the virtual server in a serverlist row. A stopped server's row has no maxclients, so read
    /// the stored value from ts3server.sqlitedb (read-only, no side effects); fall back to "use -virtual"
    /// + serverinfo, which TeamSpeak refuses while the license's running-server limit is reached (-1).
    /// </summary>
    public int MaxClients(Dictionary<string, string> row, string rootDirectory)
    {
        int max = Int(row, "virtualserver_maxclients", -1);
        if (max >= 0) return max;
        int sid = Int(row, "virtualserver_id");
        if (_storedMaxClients == null) _storedMaxClients = ReadStoredMaxClients(Path.Combine(rootDirectory ?? "", "ts3server.sqlitedb"));
        if (_storedMaxClients.TryGetValue(sid, out max)) return max;
        try
        {
            Use(sid);
            return Int(SendSingle("serverinfo"), "virtualserver_maxclients", -1);
        }
        catch (Ts3Exception)
        {
            return -1;
        }
    }

    private static Dictionary<int, int> ReadStoredMaxClients(string dbPath)
    {
        var result = new Dictionary<int, int>();
        if (!File.Exists(dbPath)) return result; // another database plugin (MariaDB) - use ServerQuery
        try
        {
            var cs = new SqliteConnectionStringBuilder { DataSource = dbPath, Mode = SqliteOpenMode.ReadOnly, Pooling = false };
            using (var db = new SqliteConnection(cs.ToString()))
            {
                db.Open();
                using (var cmd = db.CreateCommand())
                {
                    cmd.CommandText = "SELECT server_id, value FROM server_properties WHERE ident = 'virtualserver_maxclients'";
                    using (var reader = cmd.ExecuteReader())
                        while (reader.Read())
                            if (int.TryParse(Convert.ToString(reader.GetValue(1)), out var m))
                                result[Convert.ToInt32(reader.GetValue(0))] = m;
                }
            }
        }
        catch
        {
            // Unreadable database: callers fall back to ServerQuery.
        }
        return result;
    }

    public void Dispose()
    {
        try { var quit = Encoding.UTF8.GetBytes("quit\n"); _net.Write(quit, 0, quit.Length); } catch { }
        _tcp.Dispose();
    }

    public static List<Dictionary<string, string>> ParseRows(string data) =>
        data.Length == 0
            ? new List<Dictionary<string, string>>()
            : data.Split('|').Select(ParseRow).ToList();

    public static Dictionary<string, string> ParseRow(string row)
    {
        var result = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        foreach (var token in row.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries))
        {
            int eq = token.IndexOf('=');
            if (eq < 0) result[token] = "";
            else result[token.Substring(0, eq)] = Unescape(token.Substring(eq + 1));
        }
        return result;
    }

    public static int Int(Dictionary<string, string> row, string key, int fallback = 0) =>
        row.TryGetValue(key, out var v) && int.TryParse(v, out var i) ? i : fallback;

    public static string Str(Dictionary<string, string> row, string key, string fallback = "") =>
        row.TryGetValue(key, out var v) ? v : fallback;

    public static string Escape(string value)
    {
        var sb = new StringBuilder();
        foreach (char c in value ?? "")
        {
            switch (c)
            {
                case '\\': sb.Append(@"\\"); break;
                case '/': sb.Append(@"\/"); break;
                case ' ': sb.Append(@"\s"); break;
                case '|': sb.Append(@"\p"); break;
                case '\a': sb.Append(@"\a"); break;
                case '\b': sb.Append(@"\b"); break;
                case '\f': sb.Append(@"\f"); break;
                case '\n': sb.Append(@"\n"); break;
                case '\r': sb.Append(@"\r"); break;
                case '\t': sb.Append(@"\t"); break;
                case '\v': sb.Append(@"\v"); break;
                default: sb.Append(c); break;
            }
        }
        return sb.ToString();
    }

    public static string Unescape(string value)
    {
        var sb = new StringBuilder();
        for (int i = 0; i < value.Length; i++)
        {
            char c = value[i];
            if (c != '\\' || i == value.Length - 1) { sb.Append(c); continue; }
            char n = value[++i];
            switch (n)
            {
                case 's': sb.Append(' '); break;
                case 'p': sb.Append('|'); break;
                case '/': sb.Append('/'); break;
                case '\\': sb.Append('\\'); break;
                case 'a': sb.Append('\a'); break;
                case 'b': sb.Append('\b'); break;
                case 'f': sb.Append('\f'); break;
                case 'n': sb.Append('\n'); break;
                case 'r': sb.Append('\r'); break;
                case 't': sb.Append('\t'); break;
                case 'v': sb.Append('\v'); break;
                default: sb.Append('\\').Append(n); break;
            }
        }
        return sb.ToString();
    }
}

//refAssemblies: TCAdmin.SDK.dll, TCAdmin.GameHosting.SDK.dll, TCAdmin.Scripting.dll, TCAdmin.Monitor.dll, Microsoft.Data.Sqlite.dll, Microsoft.EntityFrameworkCore.dll
using System;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Net.Sockets;
using System.Text;
using TCAdmin.SDK.Database.Entities;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE


// API function "TsVirtualServers": the virtual servers of this master, for the TeamSpeak Browser page.
// TsAction = list | info | start | stop | autostart | create | delete | edit | bandwidth | logs.
// A virtual server that is a TCAdmin hosted service is listed with its service and refused for start,
// stop, autostart, edit and delete: the panel owns those, or its status and settings would drift.
// list       -> { host, servers: [{ sid, name, port, status, online, clients, maxClients, uptimeSeconds, autostart, uniqueId, service }] }
// info       TsSid -> the serverinfo row
// start/stop TsSid
// autostart  TsSid, TsAutostart
// create     TsName, TsSlots, TsPort (0 = next free) -> { sid, port, token }
// delete     TsSid (stops it first)
// edit       TsSid, TsName, TsSlots (0 = keep), TsReservedSlots, TsPassword / TsClearPassword, TsWelcomeMessage, TsHostMessage, TsHostMessageMode (0-3)
// bandwidth  TsSid -> the connection-info row
// logs       TsSid, TsLines (max 100) -> { lines, fileSize } the last lines, oldest first
var action = Action();
var panel = PanelVirtualServers();
using (var ts = Ts3Connect())
{
    switch (action)
    {
        case "list":
        {
            var rows = new List<Dictionary<string, object>>();
            foreach (var vs in ts.Send("serverlist -uid").Where(r => r.ContainsKey("virtualserver_id")).OrderBy(r => Ni(r, "virtualserver_id")))
            {
                int sid = Ni(vs, "virtualserver_id");
                bool online = Nz(vs, "virtualserver_status") == "online";
                rows.Add(new Dictionary<string, object>
                {
                    ["sid"] = sid, ["name"] = Nz(vs, "virtualserver_name"), ["port"] = Ni(vs, "virtualserver_port"),
                    ["status"] = Nz(vs, "virtualserver_status"), ["online"] = online,
                    ["clients"] = online ? Math.Max(0, Ni(vs, "virtualserver_clientsonline") - Ni(vs, "virtualserver_queryclientsonline")) : 0,
                    ["maxClients"] = ts.MaxClients(vs, ThisService.RootDirectory),
                    ["uptimeSeconds"] = online ? Ni(vs, "virtualserver_uptime") : 0,
                    ["autostart"] = Ni(vs, "virtualserver_autostart") == 1, ["uniqueId"] = Nz(vs, "virtualserver_unique_identifier"),
                    ["service"] = panel.TryGetValue(sid, out var svc) ? svc : null
                });
            }
            Globals.ReturnValue = new Dictionary<string, object> { ["host"] = ThisService.IPAddress ?? "", ["servers"] = rows };
            break;
        }
        case "info":
        {
            int sid = UseSid(ts);
            var info = ServerInfoRow(ts, sid);
            info["service"] = panel.TryGetValue(sid, out var svc) ? svc : null;
            Globals.ReturnValue = info;
            break;
        }
        case "start":
        case "stop":
        {
            int sid = RequireSid();
            RequireUnmanaged(panel, sid, action == "start" ? "Start" : "Stop");
            var reply = ts.Execute($"server{action} sid={sid}");
            // 1025 = already running, 1033 = not running: the requested state already holds.
            if (reply.ErrorId != 0 && reply.ErrorId != 1025 && reply.ErrorId != 1033) throw new Ts3Exception(reply.ErrorId, reply.ErrorMessage);
            Globals.ReturnValue = new { ok = true, sid, online = action == "start" };
            break;
        }
        case "autostart":
        {
            int sid = RequireSid();
            RequireUnmanaged(panel, sid, "Change the autostart of");
            ts.Use(sid);
            ts.Send($"serveredit virtualserver_autostart={(BoolArg("TsAutostart") ? 1 : 0)}");
            Globals.ReturnValue = new { ok = true, sid, autostart = BoolArg("TsAutostart") };
            break;
        }
        case "create":
        {
            var name = Arg("TsName").Trim(); if (name.Length == 0) throw Fail("TsName is required.");
            int slots = IntArg("TsSlots", 32); if (slots <= 0) throw Fail("TsSlots must be greater than 0.");
            int port = IntArg("TsPort");
            var row = ts.SendSingle($"servercreate virtualserver_name={Ts3Query.Escape(name)} virtualserver_maxclients={slots}" + (port > 0 ? $" virtualserver_port={port}" : ""));
            Globals.ReturnValue = new { sid = Ni(row, "sid"), port = Ni(row, "virtualserver_port"), token = Nz(row, "token") };
            break;
        }
        case "delete":
        {
            int sid = RequireSid();
            RequireUnmanaged(panel, sid, "Delete");
            var stop = ts.Execute($"serverstop sid={sid}");
            if (stop.ErrorId != 0 && stop.ErrorId != 1033) throw new Ts3Exception(stop.ErrorId, stop.ErrorMessage);
            var del = ts.Execute($"serverdelete sid={sid}");
            if (del.ErrorId != 0 && del.ErrorId != 1024) throw new Ts3Exception(del.ErrorId, del.ErrorMessage);
            Globals.ReturnValue = new { ok = true, sid };
            break;
        }
        case "edit":
        {
            int sid = RequireSid();
            RequireUnmanaged(panel, sid, "Edit");
            ts.Use(sid);
            var cmd = new StringBuilder("serveredit");
            var name = Arg("TsName").Trim();
            if (name.Length > 0) cmd.Append(" virtualserver_name=").Append(Ts3Query.Escape(name));
            if (IntArg("TsSlots") > 0) cmd.Append(" virtualserver_maxclients=").Append(IntArg("TsSlots"));
            if (GetValue<object>("TsReservedSlots") != null) cmd.Append(" virtualserver_reserved_slots=").Append(Math.Max(0, IntArg("TsReservedSlots")));
            if (BoolArg("TsClearPassword")) cmd.Append(" virtualserver_password=");
            else if (Arg("TsPassword").Length > 0) cmd.Append(" virtualserver_password=").Append(Ts3Query.Escape(Arg("TsPassword")));
            if (GetValue<object>("TsWelcomeMessage") != null) cmd.Append(" virtualserver_welcomemessage=").Append(Ts3Query.Escape(Arg("TsWelcomeMessage").Trim()));
            if (GetValue<object>("TsHostMessage") != null) cmd.Append(" virtualserver_hostmessage=").Append(Ts3Query.Escape(Arg("TsHostMessage").Trim()));
            if (GetValue<object>("TsHostMessageMode") != null) cmd.Append(" virtualserver_hostmessage_mode=").Append(Math.Clamp(IntArg("TsHostMessageMode"), 0, 3));
            if (cmd.Length == "serveredit".Length) throw Fail("Nothing to change.");
            ts.Send(cmd.ToString());
            Globals.ReturnValue = ServerInfoRow(ts, sid);
            break;
        }
        case "bandwidth":
        {
            int sid = UseSid(ts);
            var row = BandwidthRow(ts);
            row["sid"] = sid;
            Globals.ReturnValue = row;
            break;
        }
        case "logs":
        {
            UseSid(ts);
            Globals.ReturnValue = LogPage(ts, IntArg("TsLines", 100), instance: false);
            break;
        }
        default:
            throw Fail($"Unknown TsAction '{action}'. Use list, info, start, stop, autostart, create, delete, edit, bandwidth or logs.");
    }
}


// ---------------------------------------------------------------------------------------------
// API-function helpers. The TeamSpeak Browser page calls these scripts through
// TCAdmin.Script.Execute(name, { TsAction: "...", ... }); every argument is a declared script
// input variable (Ts*). The result is Globals.ReturnValue; a thrown exception is the call's error.
// Every TeamSpeak Browser function of this blueprint carries the same copy - keep them identical.
// ---------------------------------------------------------------------------------------------
string Arg(string name, string fallback = "")
{
    var value = GetValue<object>(name);
    var text = value == null ? "" : Convert.ToString(value, CultureInfo.InvariantCulture) ?? "";
    return text.Length == 0 ? fallback : text;
}
int IntArg(string name, int fallback = 0) =>
    double.TryParse(Arg(name), NumberStyles.Float, CultureInfo.InvariantCulture, out var d) ? (int)Math.Round(d) : fallback;
bool BoolArg(string name) => Arg(name).Equals("true", StringComparison.OrdinalIgnoreCase) || Arg(name) == "1";
string Action() => Arg("TsAction").Trim().ToLowerInvariant();
Exception Fail(string message) => new Exception(message);
string Nz(Dictionary<string, string> row, string key) => Ts3Query.Str(row, key);
int Ni(Dictionary<string, string> row, string key, int fallback = 0) => Ts3Query.Int(row, key, fallback);
long Nl(Dictionary<string, string> row, string key) => long.TryParse(Ts3Query.Str(row, key), out var l) ? l : 0;

/// <summary>Server groups of the selected virtual server: sgid -> name (regular groups only).</summary>
Dictionary<int, string> ServerGroups(Ts3Query ts) =>
    ts.Send("servergrouplist").Where(g => Ni(g, "type") == 1 && g.ContainsKey("sgid"))
      .ToDictionary(g => Ni(g, "sgid"), g => Nz(g, "name"));

/// <summary>Channels of the selected virtual server as browser rows, in TeamSpeak's display order.</summary>
List<Dictionary<string, object>> ChannelRows(Ts3Query ts)
{
    var rows = ts.Send("channellist -topic -flags -voice -limits").Where(c => c.ContainsKey("cid")).ToList();
    var byParent = rows.GroupBy(c => Ni(c, "pid")).ToDictionary(g => g.Key, g => g.ToList());
    var ordered = new List<Dictionary<string, object>>();
    void Walk(int pid, int depth)
    {
        if (!byParent.TryGetValue(pid, out var children)) return;
        // channel_order is the id of the channel ABOVE a channel; 0 = first.
        var remaining = children.ToList();
        int previous = 0;
        while (remaining.Count > 0)
        {
            var next = remaining.FirstOrDefault(c => Ni(c, "channel_order") == previous) ?? remaining[0];
            remaining.Remove(next);
            int cid = Ni(next, "cid");
            ordered.Add(new Dictionary<string, object>
            {
                ["cid"] = cid, ["pid"] = pid, ["depth"] = depth,
                ["name"] = Nz(next, "channel_name"), ["topic"] = Nz(next, "channel_topic"),
                ["clients"] = Ni(next, "total_clients"),
                ["maxClients"] = Ni(next, "channel_flag_maxclients_unlimited") == 1 ? -1 : Ni(next, "channel_maxclients", -1),
                ["permanent"] = Ni(next, "channel_flag_permanent") == 1,
                ["semiPermanent"] = Ni(next, "channel_flag_semi_permanent") == 1,
                ["isDefault"] = Ni(next, "channel_flag_default") == 1,
                ["passworded"] = Ni(next, "channel_flag_password") == 1,
                ["codec"] = Ni(next, "channel_codec"), ["codecQuality"] = Ni(next, "channel_codec_quality"),
                ["neededTalkPower"] = Ni(next, "channel_needed_talk_power"),
                ["neededSubscribePower"] = Ni(next, "channel_needed_subscribe_power")
            });
            previous = cid;
            Walk(cid, depth + 1);
        }
    }
    Walk(0, 0);
    return ordered;
}

