{
    var i = ts.SendSingle("serverinfo");
    bool online = Nz(i, "virtualserver_status") == "online";
    return new Dictionary<string, object>
    {
        ["sid"] = sid, ["name"] = Nz(i, "virtualserver_name"), ["status"] = Nz(i, "virtualserver_status"), ["online"] = online,
        ["port"] = Ni(i, "virtualserver_port"), ["maxClients"] = Ni(i, "virtualserver_maxclients", -1),
        ["reservedSlots"] = Ni(i, "virtualserver_reserved_slots"),
        ["clients"] = online ? Math.Max(0, Ni(i, "virtualserver_clientsonline") - Ni(i, "virtualserver_queryclientsonline")) : 0,
        ["channels"] = Ni(i, "virtualserver_channelsonline"), ["uptimeSeconds"] = online ? Ni(i, "virtualserver_uptime") : 0,
        ["autostart"] = Ni(i, "virtualserver_autostart") == 1, ["passwordProtected"] = Ni(i, "virtualserver_flag_password") == 1,
        ["welcomeMessage"] = Nz(i, "virtualserver_welcomemessage"), ["hostMessage"] = Nz(i, "virtualserver_hostmessage"),
        ["hostMessageMode"] = Ni(i, "virtualserver_hostmessage_mode"),
        ["hostBannerUrl"] = Nz(i, "virtualserver_hostbanner_url"), ["hostBannerGfxUrl"] = Nz(i, "virtualserver_hostbanner_gfx_url"),
        ["hostButtonTooltip"] = Nz(i, "virtualserver_hostbutton_tooltip"), ["hostButtonUrl"] = Nz(i, "virtualserver_hostbutton_url"),
        ["platform"] = Nz(i, "virtualserver_platform"), ["version"] = Nz(i, "virtualserver_version"),
        ["created"] = Nl(i, "virtualserver_created"), ["uniqueId"] = Nz(i, "virtualserver_unique_identifier"),
        ["minClientVersion"] = Nz(i, "virtualserver_min_client_version"),
        ["neededIdentitySecurityLevel"] = Ni(i, "virtualserver_needed_identity_security_level"),
        ["codecEncryptionMode"] = Ni(i, "virtualserver_codec_encryption_mode"),
        ["uploadQuotaMb"] = Nl(i, "virtualserver_upload_quota"), ["downloadQuotaMb"] = Nl(i, "virtualserver_download_quota"),
        ["bytesUploadedMonth"] = Nl(i, "virtualserver_month_bytes_uploaded"), ["bytesDownloadedMonth"] = Nl(i, "virtualserver_month_bytes_downloaded"),
        ["bytesSent"] = Nl(i, "connection_bytes_sent_total"), ["bytesReceived"] = Nl(i, "connection_bytes_received_total"),
        ["bandwidthSent"] = Nl(i, "connection_bandwidth_sent_last_second_total"), ["bandwidthReceived"] = Nl(i, "connection_bandwidth_received_last_second_total"),
        ["packetLoss"] = Nz(i, "virtualserver_total_packetloss_total"), ["ping"] = Nz(i, "virtualserver_total_ping"),
        ["clientConnections"] = Ni(i, "virtualserver_client_connections"), ["queryConnections"] = Ni(i, "virtualserver_query_client_connections")
    };
}

